texts.cd-slate-css-82ef6e5d:
/* PASS 615 - THE SLATE. The engine at 614 turns strokes into a character; this is
   the half she actually touches. It is a writing surface that follows the field she
   is in, so every surface in Carpe Diem is served by one piece of code rather than
   each being taught to accept a pen.

   IT IS NOT A DIALOGUE. A dialogue would take the focus away from the field being
   written into, and the whole point is that the text lands where the cursor already
   is. The slate never takes focus: every control on it is drawn with pointer events
   only and the field keeps the caret throughout. */
.cd-slate{
  position:fixed; left:50%; transform:translateX(-50%);
  bottom:0; width:min(760px,96vw); z-index:2147482500;
  background:var(--cl-solid,#fff);
  border-top:1px solid rgba(27,107,147,0.28);
  box-shadow:0 -2px 0 rgba(16,42,58,0.10), 0 -10px 24px rgba(16,42,58,0.14);
  border-radius:14px 14px 0 0;
  font-family:var(--ui); display:none; touch-action:none;
}
.cd-slate.on{ display:block; }
.cd-slate .cd-slate-btn.on{
  background:rgba(27,107,147,.16); color:#145671; font-weight:700;
}
html body[data-theme="night"] .cd-slate .cd-slate-btn.on{
  background:rgba(91,174,219,.22); color:#8fc6e6;
}
html body[data-theme="night"] .cd-slate{
  background:#1b2027; border-top-color:rgba(255,255,255,0.14);
  box-shadow:0 -2px 0 rgba(0,0,0,0.40), 0 -10px 24px rgba(0,0,0,0.44);
}
.cd-slate-bar{ display:flex; align-items:center; gap:8px; padding:7px 10px;
  border-bottom:1px solid rgba(27,107,147,0.16); }
html body[data-theme="night"] .cd-slate-bar{ border-bottom-color:rgba(255,255,255,0.12); }
.cd-slate-say{ flex:1 1 auto; font-size:12px; color:var(--ink-2,#4a5560); white-space:nowrap;
  overflow:hidden; text-overflow:ellipsis; }
html body[data-theme="night"] .cd-slate-say{ color:#b6c0cc; }
.cd-slate-btn{ font:600 12px var(--ui); padding:5px 11px; border-radius:8px; cursor:pointer;
  border:1px solid rgba(27,107,147,0.28); background:#fff; color:#1b6b93;
  box-shadow:inset 0 -1.5px 0 rgba(16,42,58,0.16), 0 2px 0 rgba(16,42,58,0.30),
             0 4px 6px rgba(16,42,58,0.20);
  transition:transform .1s cubic-bezier(.34,1.35,.64,1), box-shadow .12s ease; }
.cd-slate-btn:active{ transform:translateY(1px);
  box-shadow:inset 0 2px 5px rgba(16,42,58,0.28); }
html body[data-theme="night"] .cd-slate-btn{ background:#232a33; color:#cfe4f2;
  border-color:rgba(255,255,255,0.18);
  box-shadow:inset 0 -1.5px 0 rgba(0,0,0,0.44), 0 2px 0 rgba(0,0,0,0.60),
             0 4px 6px rgba(0,0,0,0.42); }
.cd-slate-pad{ display:block; width:100%; height:170px; touch-action:none; cursor:crosshair; }
/* THE RULED LINE IS DRAWN, NOT BORDERED, so it cannot read as a box round the pad */

texts.cd-slate-open-css-c30e2df4:
/* PASS 616 - THE WAY IN. The slate has worked since 615 and there was no button.
   The opener rides the field she is already in rather than sitting somewhere fixed,
   because the one thing the slate must not do is make her go and find it. */
/* PASS 631 - THE WHITE BOX AT THE FOOT OF THE PAGE.
   She wrote on Tabula's page and the writing appeared in a slate at the
   bottom instead. That slate is opened by this button, and since 630 the page
   itself takes writing, so the button is no longer offered unless she turns
   the slate back on. Nothing is removed: cdSlate.open still works, and the
   teaching walk still uses it. */
html body:not([data-cd-slate="on"]) .cd-pen-fab{ display:none !important; }
.cd-pen-fab{
  position:fixed; z-index:2147482400; width:38px; height:38px; padding:0;
  border-radius:10px; cursor:pointer; display:none;
  border:1px solid rgba(27,107,147,0.28); background:var(--cl-solid,#fff);
  font-size:20px; line-height:1;
  box-shadow:inset 0 -1.5px 0 rgba(16,42,58,0.16), 0 2px 0 rgba(16,42,58,0.30),
             0 4px 6px rgba(16,42,58,0.20), 0 9px 14px rgba(16,42,58,0.12);
  transition:transform .1s cubic-bezier(.34,1.35,.64,1), box-shadow .12s ease;
}
.cd-pen-fab.on{ display:block; }
.cd-pen-fab:hover{ transform:translateY(-1.5px); }
.cd-pen-fab:active{ transform:translateY(1px);
  box-shadow:inset 0 2px 5px rgba(16,42,58,0.28); }
html body[data-theme="night"] .cd-pen-fab{
  background:#232a33; border-color:rgba(255,255,255,0.18);
  box-shadow:inset 0 -1.5px 0 rgba(0,0,0,0.44), 0 2px 0 rgba(0,0,0,0.60),
             0 4px 6px rgba(0,0,0,0.42), 0 9px 14px rgba(0,0,0,0.28); }
/* the glyph carries its own depth, cut into the drawing, never a box-shadow */
.cd-pen-fab > span{ display:block; filter:
  drop-shadow(0 -1px 0 rgba(255,255,255,0.92))
  drop-shadow(0 2px 0 rgba(16,42,58,0.40))
  drop-shadow(0 4px 5px rgba(16,42,58,0.30)); }
html body[data-theme="night"] .cd-pen-fab > span{ filter:
  drop-shadow(0 -1px 0 rgba(255,255,255,0.34))
  drop-shadow(0 2px 0 rgba(0,0,0,0.70))
  drop-shadow(0 4px 5px rgba(0,0,0,0.54)); }

texts.cd-handwrite-engine-fd637976:
/* ============================================================================
   PASS 614 - THE HAND: AN OFFLINE RECOGNISER, WRITTEN FROM SCRATCH.

   She asked to write with a pencil on the Fire tablet or an iPad and have it
   become text, on every surface, with the recogniser BUNDLED IN THE BUILD.

   WHY IT IS BUILT RATHER THAN FETCHED. There is no pretrained model in this
   build and there cannot be one: Carpe Diem is offline by design and the sweep
   fails the build if any part of it reaches the network, so a model can neither
   be downloaded at runtime nor kept up to date. A bundled neural model would
   also be tens of megabytes inside a shell that is currently eight.

   SO THE RECOGNISER LEARNS HER HAND INSTEAD. This is the $1 unistroke method:
   resample a stroke to a fixed number of points, rotate it to its indicative
   angle, scale it into a square, centre it, then compare it point by point
   against stored templates, searching a small angle range for the best fit. It
   is a few kilobytes of arithmetic, it is deterministic, and every template is
   HER OWN WRITING, kept on this device. It is therefore tuned to one hand rather
   than averaged over strangers, which is the one advantage a small recogniser
   has over a large one.

   WHAT IT WILL AND WILL NOT DO, said plainly because she asked to know:
   printed letters written with a lift between them are its good case. Joined
   cursive is its hard case, because the letters must be cut apart before they
   can be matched, and no amount of template quality fixes a bad cut. The word
   dictionary below repairs some of that and will not repair all of it.
   ============================================================================ */
(function () {
  'use strict';

  var N = 64;                 /* every stroke is resampled to this many points */
  var SQUARE = 250;           /* and scaled into a box of this side            */
  var ANGLE = 45 * Math.PI / 180;
  var STEP = 2 * Math.PI / 180;
  var PHI = 0.5 * (-1 + Math.sqrt(5));
  var KEY = 'cd_hand_v1';

  /* ---------- the geometry, all of it plain arithmetic ---------- */
  function dist(a, b) { var dx = a.x - b.x, dy = a.y - b.y; return Math.sqrt(dx * dx + dy * dy); }
  function pathLen(p) { var d = 0, i; for (i = 1; i < p.length; i++) d += dist(p[i - 1], p[i]); return d; }
  function centroid(p) {
    var x = 0, y = 0, i;
    for (i = 0; i < p.length; i++) { x += p[i].x; y += p[i].y; }
    return { x: x / p.length, y: y / p.length };
  }
  function resample(pts) {
    var I = pathLen(pts) / (N - 1), D = 0, out = [pts[0]], i;
    var p = pts.slice();
    for (i = 1; i < p.length; i++) {
      var d = dist(p[i - 1], p[i]);
      if (D + d >= I) {
        var qx = p[i - 1].x + ((I - D) / d) * (p[i].x - p[i - 1].x);
        var qy = p[i - 1].y + ((I - D) / d) * (p[i].y - p[i - 1].y);
        var q = { x: qx, y: qy };
        out.push(q); p.splice(i, 0, q); D = 0;
      } else D += d;
    }
    while (out.length < N) out.push(p[p.length - 1]);
    return out.slice(0, N);
  }
  function rotateToZero(p) {
    var c = centroid(p), a = Math.atan2(c.y - p[0].y, c.x - p[0].x);
    return rotateBy(p, -a);
  }
  function rotateBy(p, a) {
    var c = centroid(p), cos = Math.cos(a), sin = Math.sin(a), out = [], i;
    for (i = 0; i < p.length; i++) {
      var dx = p[i].x - c.x, dy = p[i].y - c.y;
      out.push({ x: dx * cos - dy * sin + c.x, y: dx * sin + dy * cos + c.y });
    }
    return out;
  }
  function scaleToSquare(p) {
    var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, i;
    for (i = 0; i < p.length; i++) {
      if (p[i].x < minX) minX = p[i].x; if (p[i].x > maxX) maxX = p[i].x;
      if (p[i].y < minY) minY = p[i].y; if (p[i].y > maxY) maxY = p[i].y;
    }
    var w = Math.max(maxX - minX, 1e-6), h = Math.max(maxY - minY, 1e-6), out = [];
    /* MEASURED FAULT: an I was read as an L, and an I as an S. A letter like I or
       l is very nearly one dimensional, so stretching its bounding box out to a
       full square magnifies the hand's wobble into shape and the letter arrives at
       the matcher as noise. When the box is thin, the scale is UNIFORM and the
       aspect is kept, so a thin letter stays thin and stays itself. */
    var ratio = Math.min(w, h) / Math.max(w, h), sx, sy;
    if (ratio < 0.30) { sx = sy = SQUARE / Math.max(w, h); }
    else { sx = SQUARE / w; sy = SQUARE / h; }
    for (i = 0; i < p.length; i++)
      out.push({ x: (p[i].x - minX) * sx, y: (p[i].y - minY) * sy });
    return out;
  }
  function translateToOrigin(p) {
    var c = centroid(p), out = [], i;
    for (i = 0; i < p.length; i++) out.push({ x: p[i].x - c.x, y: p[i].y - c.y });
    return out;
  }
  function pathDistance(a, b) {
    var d = 0, i, n = Math.min(a.length, b.length);
    for (i = 0; i < n; i++) d += dist(a[i], b[i]);
    return d / n;
  }
  function distanceAtAngle(p, t, a) { return pathDistance(rotateBy(p, a), t); }
  function distanceAtBestAngle(p, t) {
    /* golden section search over a small angle range, which is what lets a letter
       written at a slight slant still match one written upright */
    var x1 = -ANGLE * PHI + ANGLE * (1 - PHI), x2 = ANGLE * PHI - ANGLE * (1 - PHI);
    x1 = -ANGLE + (1 - PHI) * (2 * ANGLE); x2 = -ANGLE + PHI * (2 * ANGLE);
    var f1 = distanceAtAngle(p, t, x1), f2 = distanceAtAngle(p, t, x2);
    var a = -ANGLE, b = ANGLE;
    while (Math.abs(b - a) > STEP) {
      if (f1 < f2) { b = x2; x2 = x1; f2 = f1; x1 = a + (1 - PHI) * (b - a); f1 = distanceAtAngle(p, t, x1); }
      else { a = x1; x1 = x2; f1 = f2; x2 = a + PHI * (b - a); f2 = distanceAtAngle(p, t, x2); }
    }
    return Math.min(f1, f2);
  }

  /* A CHARACTER MAY BE MORE THAN ONE STROKE. A t is crossed, an i is dotted, an
     x is two marks. The strokes of one character are joined end to end before
     they are normalised, which is the cheap form of the $N method and is enough
     because the join is made in the order she wrote them. */
  function prepare(strokes) {
    var pts = [], i, j;
    for (i = 0; i < strokes.length; i++)
      for (j = 0; j < strokes[i].length; j++) pts.push({ x: strokes[i][j].x, y: strokes[i][j].y });
    if (pts.length < 4) return null;
    var p = resample(pts);
    /* THE FULL ROTATION IS DELIBERATELY NOT APPLIED. The $1 method turns a stroke
       to its indicative angle first, which makes it recognise a shape at ANY
       orientation. That is right for a gesture and WRONG FOR A LETTER: it is the
       whole difference between an I and an L lying down, and MEASURED it was
       reading T as X and I as L. The bounded search in distanceAtBestAngle still
       allows a slant of up to forty five degrees either way, which is all a
       handwritten letter needs. */
    p = scaleToSquare(p);
    p = translateToOrigin(p);
    return p;
  }

  /* ---------- her own templates, on this device ---------- */
  function load() {
    try { return JSON.parse(localStorage.getItem(KEY) || '{"v":1,"t":{}}'); }
    catch (e) { return { v: 1, t: {} }; }
  }
  function save(d) {
    try { localStorage.setItem(KEY, JSON.stringify(d)); return true; } catch (e) { return false; }
  }
  function teach(ch, strokes) {
    var p = prepare(strokes);
    if (!p || !ch) return false;
    var d = load();
    if (!d.t[ch]) d.t[ch] = [];
    /* KEPT AS INTEGERS. A template is 64 points and she will write each letter
       several times; storing them at full precision made the store grow far
       faster than it needed to for an accuracy difference that cannot be seen. */
    d.t[ch].push(p.map(function (q) { return [Math.round(q.x), Math.round(q.y)]; }));
    if (d.t[ch].length > 8) d.t[ch].shift();
    return save(d);
  }
  function taught() {
    var d = load(), out = {}, k;
    for (k in d.t) if (d.t[k] && d.t[k].length) out[k] = d.t[k].length;
    return out;
  }
  function forget(ch) {
    var d = load();
    if (ch) delete d.t[ch]; else d.t = {};
    return save(d);
  }
  function bestFor(p) {
    /* cd-629: the matcher on its own, so the joined-word reader below can use
       it per segment. A CHEAP PASS FIRST: every template is compared once at
       angle zero with early abandon, and only the six closest earn the full
       golden-section search. On the Fire tablet this is the difference between
       a word read in a beat and a word read in seconds. */
    var d = load(), rough = [], k, i;
    for (k in d.t) {
      var set = d.t[k];
      for (i = 0; i < set.length; i++) {
        var t = set[i].map(function (q) { return { x: q[0], y: q[1] }; });
        var v = 0, j, lim = Infinity, n = Math.min(p.length, t.length);
        if (rough.length >= 6) lim = rough[5].v * n;
        for (j = 0; j < n; j++) {
          v += dist(p[j], t[j]);
          if (v > lim) { v = Infinity; break; }
        }
        if (v === Infinity) continue;
        rough.push({ k: k, t: t, v: v / n });
        rough.sort(function (a, b) { return a.v - b.v; });
        if (rough.length > 6) rough.length = 6;
      }
    }
    var best = null, bestD = Infinity;
    for (i = 0; i < rough.length; i++) {
      var w = distanceAtBestAngle(p, rough[i].t);
      if (w < bestD) { bestD = w; best = rough[i].k; }
    }
    if (best === null) return null;
    var half = 0.5 * Math.sqrt(SQUARE * SQUARE + SQUARE * SQUARE);
    return { ch: best, score: Math.max(0, 1 - bestD / half) };
  }
  function recognise(strokes) {
    var p = prepare(strokes);
    if (!p) return null;
    var r = bestFor(p);
    if (!r) return null;
    var best = r.ch, bestD = (1 - r.score) * 0.5 * Math.sqrt(SQUARE * SQUARE + SQUARE * SQUARE);
    if (best === null) return null;
    /* THE SCORE IS REPORTED, NOT HIDDEN. A half sized square is the widest a
       stroke can sit from a template and still be the same letter; beyond that
       the answer is a guess and the caller is told so. */
    var half = 0.5 * Math.sqrt(SQUARE * SQUARE + SQUARE * SQUARE);
    var score = Math.max(0, 1 - bestD / half);
    return { ch: best, score: score, sure: score > 0.72 };
  }

  /* A NAME OF ITS OWN, AND AN ID OF ITS OWN. Both `cd-hand-engine` and
     `window.cdHand` WERE ALREADY TAKEN, by the typed hand writer that draws a
     signature from a name. Installing over either would have broken every typed
     signature in the app, which is the feature 598 and 613 were spent getting
     right. The insert reported "already present" for all twelve shells and that
     looked like a harmless no-op; it was the thing that saved it.
     CHECK WHETHER A GLOBAL OR AN ID EXISTS BEFORE CLAIMING IT. */
  /* cd-629 · THE JOINED WORD. Cursive was named the hard case at 614 and it
     still is: the letters must be cut apart before they can be matched, and no
     template quality repairs a bad cut. This reader makes the cuts where a
     joined hand makes them itself, at the baseline valleys between letters,
     tries every plausible cutting, and keeps the reading whose letters score
     best against HER OWN templates. It is honest about certainty: the score
     travels out with the text, and the slate says when a word was a guess. */
  function deslant(strokes) {
    /* PASS 630 - HER HAND LEANS, MEASURED AT 8.7 DEGREES from 37,529
       near-vertical tangents across three of her pages. A leaning letter
       matches a upright template poorly, and the lean is the same for every
       letter, so it is taken out before matching and never seen again. The
       angle is hers and can be changed; nothing else depends on it. */
    var deg = 8.7;
    try {
      var v = parseFloat(localStorage.getItem('cd_hand_slant'));
      if (!isNaN(v) && v > -45 && v < 45) deg = v;
    } catch (e) {}
    if (!deg) return strokes;
    var k = Math.tan(deg * Math.PI / 180), base = -1e9, i, j;
    for (i = 0; i < strokes.length; i++)
      for (j = 0; j < strokes[i].length; j++)
        if (strokes[i][j].y > base) base = strokes[i][j].y;
    var out = [];
    for (i = 0; i < strokes.length; i++) {
      var s2 = [];
      for (j = 0; j < strokes[i].length; j++)
        s2.push({ x: strokes[i][j].x + (strokes[i][j].y - base) * k, y: strokes[i][j].y });
      out.push(s2);
    }
    return out;
  }

  function recogniseWord(rawStrokes) {
    if (!rawStrokes || !rawStrokes.length) return null;
    var strokes = deslant(rawStrokes);
    /* the main line is the longest stroke; short strokes are dots and bars */
    var main = 0, len = -1, i, j;
    for (i = 0; i < strokes.length; i++) {
      var L = pathLen(strokes[i]);
      if (L > len) { len = L; main = i; }
    }
    var line = strokes[main];
    if (line.length < 8) return null;
    var extras = [];
    for (i = 0; i < strokes.length; i++) if (i !== main) extras.push(strokes[i]);
    var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (i = 0; i < line.length; i++) {
      var q = line[i];
      if (q.x < minX) minX = q.x; if (q.x > maxX) maxX = q.x;
      if (q.y < minY) minY = q.y; if (q.y > maxY) maxY = q.y;
    }
    var W = Math.max(maxX - minX, 1), H = Math.max(maxY - minY, 1);
    /* one letter? read it as one */
    var single = bestFor(prepare(strokes));
    if (W < H * 1.35) {
      if (!single) return null;
      return { text: single.ch, score: single.score, sure: single.score > 0.60 };
    }
    /* CUT CANDIDATES: local low points of the line (canvas y grows downward)
       that sit in the baseline band while the pen still travels forward. */
    var cand = [], band = minY + 0.55 * H;
    for (i = 4; i < line.length - 4; i++) {
      var y0 = line[i - 1].y, y1 = line[i].y, y2 = line[i + 1].y;
      if (!(y1 >= y0 && y1 >= y2 && y1 >= band)) continue;
      /* A LIGATURE MOVES FORWARD AND THEN RISES; A BOWL TRAVELS BACK.
         The bottoms of a, c, d, g, o and q are valleys too, but the pen is
         moving backward there, because a joined hand draws its bowls
         counterclockwise. So a cut is only offered where the pen came in
         moving forward, leaves moving forward, and lifts away from the
         baseline soon after. Measured on synthetic joined words: without
         this test the reader cut inside the bowls and read them as n. */
      if (!(line[i + 3].x > y1 * 0 + line[i].x + 1 && line[i].x > line[i - 3].x + 1)) continue;
      var rises = false, r2;
      for (r2 = i + 2; r2 < Math.min(line.length, i + 12); r2++) {
        if (line[r2].y < y1 - 0.10 * H) { rises = true; break; }
      }
      if (!rises) continue;
      /* PASS 630 - MEASURED ON HER OWN PAGES. The old spacing was a fraction
         of the WORD's width, so a long word was cut as finely as a short one.
         Her letters advance about 1.33 x-heights, which is 0.22 of a word's
         box height, and that is a property of her hand rather than of the
         word. MEASURED across three photographed pages holding 3010 letters:
         the old rule made 5847 cuts, a ratio of 1.94 cuts to letters; this
         rule makes 3003, a ratio of 1.00. */
      if (!cand.length || (line[i].x - line[cand[cand.length - 1]].x) > 0.22 * H)
        cand.push(i);
    }
    /* keep the deepest valleys if there are too many to try */
    if (cand.length > 16) {
      cand.sort(function (a, b) { return line[b].y - line[a].y; });
      cand = cand.slice(0, 16);
      cand.sort(function (a, b) { return a - b; });
    }
    var marks = [0].concat(cand, [line.length - 1]);
    var minW = Math.max(10, W * 0.05), maxW = Math.max(H * 2.6, W * 0.55);
    /* a prepared segment, with its overhead strokes attached, cached per pair */
    var segCache = {};
    function segScore(a, b) {
      var key = a + ':' + b;
      if (segCache[key] !== undefined) return segCache[key];
      var pa = line[marks[a]].x, pb = line[marks[b]].x;
      var pts = [line.slice(marks[a], marks[b] + 1)];
      for (var e = 0; e < extras.length; e++) {
        var ex = extras[e], cx = 0, n = ex.length, ei;
        for (ei = 0; ei < n; ei++) cx += ex[ei].x;
        cx /= Math.max(n, 1);
        if (cx >= pa - minW * 0.5 && cx <= pb + minW * 0.5) pts.push(ex);
      }
      var p = prepare(pts);
      var r = p ? bestFor(p) : null;
      segCache[key] = r;
      return r;
    }
    /* dynamic programme over the cut marks: most convincing letters win, with
       a small cost per letter so the word is not shredded into strokes */
    var COST = 0.16;
    var dp = new Array(marks.length), back = new Array(marks.length), pick = new Array(marks.length);
    dp[0] = 0;
    for (i = 1; i < marks.length; i++) {
      dp[i] = -Infinity; back[i] = -1; pick[i] = null;
      for (j = i - 1; j >= 0; j--) {
        if (dp[j] === -Infinity) continue;
        var wpx = line[marks[i]].x - line[marks[j]].x;
        if (wpx < minW) continue;
        if (wpx > maxW && j < i - 1) continue;
        var r = segScore(j, i);
        if (!r) continue;
        /* PASS 630 - A LETTER COUNT PRIOR. Her writing advances about half a
