/* PASS 615 - THE SLATE.
   CAPTURE. Pointer events, so a Fire pencil, an Apple Pencil, a mouse and a finger
   all arrive the same way. A pen is preferred when one is present: if any stroke of
   a session comes from `pointerType === 'pen'`, later touches are ignored, which is
   what stops the heel of a hand resting on a tablet from drawing.

   SEGMENTATION. A character ends when the pen has been up for a moment, or when the
   next stroke starts clearly to the right of everything written so far. Both are
   needed: the pause catches a letter finished and considered, the gap catches a
   quick writer who never pauses. A wider gap still is a space.

   INSERTION. The text goes to the field that had the caret before the slate opened,
   through the same path a keypress would take, so an app that listens for input sees
   what it expects and nothing needs teaching about handwriting. */
(function () {
  'use strict';
  var PAUSE = 700;      /* ms of pen-up that ends a character */
  var PAUSEJ = 950;     /* joined writing pauses longer, a word takes time */
  var GAPCH = 0.55;     /* fraction of a letter width that ends a character */
  var GAPSP = 1.60;     /* and that means a space */

  var el = null, pad = null, ctx = null, say = null;
  var strokes = [], cur = null, target = null, timer = null;
  var lastBox = null, penSeen = false, teachCh = null, out = '';
  var joined = false;
  try { joined = localStorage.getItem('cd_hand_joined') === '1'; } catch (e) {}

  function field() {
    var a = document.activeElement;
    if (a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.isContentEditable)) return a;
    return null;
  }
  function tell(t) { if (say) say.textContent = t; }

  function put(text) {
    var f = target;
    if (!f || !f.isConnected) { tell('The writing had nowhere to go.'); return; }
    try {
      f.focus({ preventScroll: true });
      /* cd-629: the field may live in another same-origin document, a float or
         an exported window, so the selection and the text node come from ITS
         document, never from this one */
      var FD = f.ownerDocument || document;
      var FW = FD.defaultView || window;
