      } else {
        var s = f.selectionStart == null ? f.value.length : f.selectionStart;
        var e = f.selectionEnd == null ? s : f.selectionEnd;
        f.value = f.value.slice(0, s) + text + f.value.slice(e);
        try { f.selectionStart = f.selectionEnd = s + text.length; } catch (x) {}
      }
