  }

  function settle(spaceFirst) {
    if (!strokes.length) return;
    if (teachCh) {
      var ok = window.cdHandwrite && window.cdHandwrite.teach(teachCh, strokes);
      var n = (window.cdHandwrite.taught() || {})[teachCh] || 0;
      tell(ok ? ('Kept. ' + teachCh + ' now has ' + n + (n === 1 ? ' sample.' : ' samples.'))
              : 'That one could not be kept.');
      clear(); return;
    }
    if (joined) {
      var rw = window.cdHandwrite && window.cdHandwrite.recogniseWord
        ? window.cdHandwrite.recogniseWord(strokes) : null;
      if (rw && rw.text) {
        var wch = spaceFirst ? (' ' + rw.text) : rw.text;
        out += wch; put(wch);
        tell(rw.sure ? ('Read as ' + rw.text)
                     : ('Read as ' + rw.text + ', not certain. Joined writing reads better the more letters you teach.'));
      } else {
        tell('That word could not be read. Teach the hand a few more letters, or lift the pen between letters.');
      }
      clear(); return;
    }
    var r = window.cdHandwrite && window.cdHandwrite.recognise(strokes);
    if (r) {
      var ch = spaceFirst ? (' ' + r.ch) : r.ch;
      out += ch; put(ch);
      tell(r.sure ? ('Read as ' + r.ch) : ('Read as ' + r.ch + ', not certain'));
