  function build() {
    if (el) return el;
    el = document.createElement('div');
    el.className = 'cd-slate';
    el.setAttribute('role', 'group');
    el.setAttribute('aria-label', 'Write by hand');
    el.innerHTML =
      '<div class="cd-slate-bar">' +
      '<span class="cd-slate-say">Write a letter at a time. Pause, and it becomes text.</span>' +
      '<button type="button" class="cd-slate-btn" data-a="mode">Joined hand</button>' +
      '<button type="button" class="cd-slate-btn" data-a="space">Space</button>' +
      '<button type="button" class="cd-slate-btn" data-a="back">Back</button>' +
      '<button type="button" class="cd-slate-btn" data-a="clear">Clear</button>' +
      '<button type="button" class="cd-slate-btn" data-a="close">Close</button>' +
      '</div><canvas class="cd-slate-pad"></canvas>';
    document.body.appendChild(el);
    pad = el.querySelector('.cd-slate-pad');
    say = el.querySelector('.cd-slate-say');
    ctx = pad.getContext('2d');

    /* NOTHING ON THE SLATE MAY TAKE THE FOCUS, or the field loses its caret and the
       text has nowhere to land. Every control acts on pointerdown and refuses focus. */
    el.addEventListener('pointerdown', function (ev) {
      var b = ev.target.closest ? ev.target.closest('.cd-slate-btn') : null;
      if (!b) return;
      ev.preventDefault(); ev.stopPropagation();
      var a = b.getAttribute('data-a');
      if (a === 'mode') {
        joined = !joined;
        try { localStorage.setItem('cd_hand_joined', joined ? '1' : '0'); } catch (x) {}
        b.classList.toggle('on', joined);
        tell(joined ? 'Joined hand. Write a whole word, then pause.'
                    : 'Letter by letter again. Pause after each one.');
      }
      else if (a === 'space') { out += ' '; put(' '); tell('Space.'); }
      else if (a === 'back') {
        if (strokes.length) { strokes.pop(); draw(); tell('Last stroke taken back.'); }
        else { put(''); tell('Nothing on the slate to take back.'); }
      }
      else if (a === 'clear') { clear(); tell('Slate cleared.'); }
      else if (a === 'close') api.close();
    }, true);

    function pt(ev) {
      var r = pad.getBoundingClientRect();
      return { x: (ev.clientX - r.left) * (pad.width / r.width),
               y: (ev.clientY - r.top) * (pad.height / r.height) };
    }
    pad.addEventListener('pointerdown', function (ev) {
      /* PALM REJECTION, the cheap and reliable kind: once a pen has been seen in
         this session, touches are no longer strokes. */
      if (ev.pointerType === 'pen') penSeen = true;
      else if (penSeen && ev.pointerType === 'touch') return;
      ev.preventDefault();
      if (timer) { clearTimeout(timer); timer = null; }
      var p = pt(ev);
      if (!joined && lastBox && strokes.length) {
        /* the per-letter gap rules are for printed letters; a joined word
           spans the slate and settles on the pause alone */
        var w = Math.max(lastBox.w, lastBox.h, 18);
        if (p.x > lastBox.r + w * GAPSP) { settle(false); pendingSpace = true; }
        else if (p.x > lastBox.r + w * GAPCH) { settle(false); }
      }
      cur = [p]; strokes.push(cur);
      try { pad.setPointerCapture(ev.pointerId); } catch (x) {}
      draw();
    });
    pad.addEventListener('pointermove', function (ev) {
      if (!cur) return;
      ev.preventDefault();
      cur.push(pt(ev)); draw();
    });
    var pendingSpace = false;
    function up(ev) {
      if (!cur) return;
      try { pad.releasePointerCapture(ev.pointerId); } catch (x) {}
      cur = null;
      lastBox = boxOf(strokes);
      if (timer) clearTimeout(timer);
      timer = setTimeout(function () {
        var sp = pendingSpace; pendingSpace = false;
        settle(sp);
      }, (joined && !teachCh) ? PAUSEJ : PAUSE);
    }
    pad.addEventListener('pointerup', up);
    pad.addEventListener('pointercancel', up);
    return el;
  }

  function size() {
    if (!pad) return;
    var r = pad.getBoundingClientRect();
    pad.width = Math.max(320, Math.round(r.width));
    pad.height = 170;
    draw();
  }

  var api = {
    open: function (opts) {
      build();
      target = (opts && opts.into) || field();
      teachCh = (opts && opts.teach) || null;
      out = ''; penSeen = false;
      el.classList.add('on');
      try {
        var mb = el.querySelector('[data-a="mode"]');
        if (mb) mb.classList.toggle('on', joined);
      } catch (x) {}
      size(); clear();
      tell(teachCh ? ('Write the letter ' + teachCh + ', then pause.')
                   : (target ? (joined ? 'Joined hand. Write a whole word, then pause.'
                                       : 'Write a letter at a time. Pause, and it becomes text.')
                             : 'Put the cursor in a field first, then open the slate.'));
