    },
    close: function () { if (el) el.classList.remove('on'); if (timer) clearTimeout(timer); clear(); },
    isOpen: function () { return !!(el && el.classList.contains('on')); },
    teachMode: function (ch) { return api.open({ teach: ch }); },
    text: function () { return out; }
  };
