  /* PASS 630 - the surface writer needs the same careful insertion, so the
     slate lends it rather than keeping a second copy that could drift. */
  api.putInto = function (f, text) {
    var keep = target;
    target = f;
    try { put(text); } finally { target = keep; }
  };
