  window.cdSlate = api;
})();

texts.cd-slate-open-a89b358a:
/* PASS 616 - THE OPENER AND THE TEACH FLOW.

   THE OPENER FOLLOWS THE CARET. A pen button in a fixed corner would mean leaving
   the sentence to go and find it, so instead one button appears beside whichever
   field has the focus and moves with it. It appears only when there is somewhere for
   handwriting to land, which is also the honest signal that the slate would work.

   IT MUST NOT STEAL THE FOCUS, the same rule the slate itself lives by: the field
   has to keep the caret or the writing has nowhere to go. It acts on pointerdown and
   preventDefaults, and it captures the field BEFORE opening rather than trusting
   activeElement afterwards.

   THE TEACH FLOW walks the alphabet. She writes a letter, it is kept, and the walk
   moves on. Three samples of each is the default because the 614 measurements were
   taken at four and held up at three; more is better and she can always add. The
   walk is resumable: it starts at the first letter with fewest samples, so putting
   it down and coming back does not begin again from A. */
(function () {
  'use strict';
  var LETTERS = 'abcdefghijklmnopqrstuvwxyz0123456789'.split('');
  var WANT = 3;
  var fab = null, at = null;

  function isField(a) {
    return !!(a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.isContentEditable)
              && !a.closest('.cd-slate'));
  }
  function build() {
    if (fab) return fab;
    fab = document.createElement('button');
    fab.type = 'button';
    fab.className = 'cd-pen-fab';
    fab.title = 'Write this by hand';
    fab.setAttribute('aria-label', 'Write this by hand');
    fab.innerHTML = '<span>\u270e</span>';
    fab.addEventListener('pointerdown', function (ev) {
      ev.preventDefault(); ev.stopPropagation();
      try { if (window.cdSlate) window.cdSlate.open({ into: at }); } catch (e) {}
    }, true);
    document.body.appendChild(fab);
    return fab;
  }
  function place(a) {
    /* cd-715: when writing by hand is off, no pen chip appears and none of its
       focus/scroll repositioning runs, so plain typing on a tablet is never
       touched by it. */
    try { if (localStorage.getItem('cd_ink_off') === '1') { if (fab) fab.classList.remove('on'); at = null; return; } } catch (e) {}
    build();
    at = a;
    if (!a) { fab.classList.remove('on'); return; }
    var r = a.getBoundingClientRect();
    if (r.width < 40 || r.height < 14) { fab.classList.remove('on'); return; }
    var top = Math.min(Math.max(6, r.top + 4), window.innerHeight - 44);
    var left = Math.min(r.right + 6, window.innerWidth - 44);
    if (left < 6) left = 6;
    /* cd-724: the chip must never be placed off a narrow screen */
    var __cvw = Math.max(240, window.innerWidth || 0), __cvh = Math.max(240, window.innerHeight || 0);
    top = Math.max(8, Math.min(__cvh - 52, top)); left = Math.max(8, Math.min(__cvw - 52, left));
    fab.style.top = Math.round(top) + 'px';
    fab.style.left = Math.round(left) + 'px';
    fab.classList.add('on');
  }
  function watch() {
    document.addEventListener('focusin', function (ev) {
      var a = ev.target;
      if (isField(a)) place(a); else if (!(a && a.closest && a.closest('.cd-slate'))) place(null);
    }, true);
    document.addEventListener('focusout', function () {
      setTimeout(function () {
        var a = document.activeElement;
        if (!isField(a) && !(a && a.closest && a.closest('.cd-slate'))) place(null);
      }, 60);
    }, true);
    window.addEventListener('scroll', function () { if (at) place(at); }, true);
    window.addEventListener('resize', function () { if (at) place(at); });
  }

  /* ---------- the teach flow ---------- */
  function counts() {
    try { return (window.cdHandwrite && window.cdHandwrite.taught()) || {}; } catch (e) { return {}; }
  }
  function nextLetter() {
    var c = counts(), i, low = null, lowN = Infinity;
    for (i = 0; i < LETTERS.length; i++) {
      var n = c[LETTERS[i]] || 0;
      if (n < WANT && n < lowN) { lowN = n; low = LETTERS[i]; }
    }
    return low;
  }
  function progress() {
    var c = counts(), done = 0, i;
    for (i = 0; i < LETTERS.length; i++) if ((c[LETTERS[i]] || 0) >= WANT) done++;
    return { done: done, total: LETTERS.length };
  }
  function teachNext() {
    var ch = nextLetter();
    if (!ch) return null;
    try { if (window.cdSlate) window.cdSlate.teachMode(ch); } catch (e) {}
    return ch;
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', watch);
  else watch();

  window.cdPen = {
    open: function (f) { place(f || document.activeElement); if (window.cdSlate) window.cdSlate.open({ into: at }); },
    teachNext: teachNext, nextLetter: nextLetter, progress: progress,
    letters: LETTERS, want: WANT,
    forgetHand: function () { try { return window.cdHandwrite.forget(); } catch (e) { return false; } }
  };
})();

texts.cd-ink-anywhere-94cd2091:
/* ============================================================================
   PASS 631 - SHE WRITES ON THE PAGE ITSELF, AND THE FIRE SURVIVES IT.

   WHAT 630 GOT WRONG, both found in her report and confirmed in the code:
     - it repainted the WHOLE sheet on every pointermove. The sheet is the
       viewport times the device pixel ratio, so on a Fire that is roughly
       nine megapixels cleared and redrawn dozens of times a second. That is
       the lag, and the memory it holds is very plausibly the crash.
     - it only accepted pointerType 'pen'. Her Fire stylus reports itself as
       a touch, so nothing happened on the surface and the only way in left
       was the pen button and the slate at the foot of the page, which is
       exactly the white box she did not want.

   WHAT THIS DOES INSTEAD:
     - one segment is drawn per move, never the whole sheet;
     - the backing store is capped at 1.25 times CSS pixels;
     - move and up are listened for ONLY while a stroke is in progress;
     - the sheet is released the moment the writing settles;
     - a touch writes when it begins on something writable, which is when
       writing is meant and scrolling is not; a pen writes anywhere;
     - the strokes are smoothed and evenly resampled before they are read,
       because a tablet's pointer stream is coarse and every wobble was
       reaching the matcher;
     - the slant is measured from her own strokes, where the pen's order is
       known, so the everyday hand and the copperplate hand both read;
     - a writing surface is given inputmode none, so the caret sits where it
       should and the device keyboard stays away. */
(function () {
  'use strict';
  if (window.cdInk) return;
  var PAUSE = 750, PAUSEJ = 1000, MAXDPR = 1.25;
  var on = true, finger = true, anywhere = false;
  /* cd-724: on a touch-first device the pen heuristic misfires - her Fire drew
     blue lines across the page on finger scrolls. There, ink enters only through
     the chip-chosen fields and the slate. */
  var __cdCoarse = false; try { __cdCoarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches); } catch (e) {}
  on = false; /* cd-808: the handwrite engine is retired at her instruction - it lagged the Fire tablet */ try { localStorage.setItem('cd_ink_off','1'); } catch (e) {}
  try { finger = localStorage.getItem('cd_ink_finger') !== '0'; } catch (e) {}
  try { anywhere = localStorage.getItem('cd_ink_anywhere') === '1'; } catch (e) {}

  var sheet = null, ctx = null, strokes = [], cur = null, timer = null;
  var field = null, lastField = null, dpr = 1;

  function editable(n) {
    if (!n || n.nodeType !== 1) return false;
    var t = (n.tagName || '').toLowerCase();
    if (t === 'textarea') return !n.disabled && !n.readOnly;
    if (t === 'input') {
      var ty = (n.type || 'text').toLowerCase();
      return !n.disabled && !n.readOnly &&
        ['text', 'search', 'email', 'url', 'tel', 'number'].indexOf(ty) >= 0;
    }
    return n.isContentEditable === true;
  }
  function upFrom(n) {
    while (n && n !== document.body) {
      if (editable(n)) return n;
      n = n.parentElement;
    }
