      var stack = document.elementsFromPoint(x, y);
      for (i = 0; i < stack.length; i++) {
        hit = upFrom(stack[i]);
        if (hit) return hit;
      }
    } catch (e) {
      hit = upFrom(document.elementFromPoint(x, y));
      if (hit) return hit;
    }
    var all = document.querySelectorAll('textarea,input,[contenteditable]');
    var best = null, area = Infinity;
    for (i = 0; i < all.length; i++) {
      if (!editable(all[i])) continue;
      var r = all[i].getBoundingClientRect();
      if (r.width < 40 || r.height < 16) continue;
      if (x < r.left || x > r.right || y < r.top || y > r.bottom) continue;
      var a = r.width * r.height;
      if (a < area) { area = a; best = all[i]; }
    }
    return best;
  }
  function biggestField() {
    var all = document.querySelectorAll('textarea,input,[contenteditable]'), best = null, area = 0, i;
    for (i = 0; i < all.length; i++) {
