    for (i = 1; i < st.length - 1; i++) {
      out.push({
        x: (st[i - 1].x + 2 * st[i].x + st[i + 1].x) / 4,
        y: (st[i - 1].y + 2 * st[i].y + st[i + 1].y) / 4
